{"content": "{
  "main_characters": [
    {
      "name": "沈念",
      "role": "protagonist",
      "identity": "，高三学生，长期遭受霸凌",
      "traits": ["倔强", "内心敏感", "习惯性隐忍", "渴望被看见", "外壳坚硬"],
      "overt_motivation": "躲避霸凌者，找到一个安全的空间",
      "covert_motivation": "渴望被关注、被看见——长期被霸凌让她成为隐形人",
      "secret_fear": "被彻底遗忘（她害怕的事恰恰是规则施加的代价）",
      "misperception_of_other": "以为世界上没有人会在乎她",
      "hidden_connection": "她是唯一一个能看见沈逸的人"
    },
    {
      "name": "沈逸",
      "role": "deuteragonist",
      "identity": "三年前失踪的学霸，被困在透明层",
      "traits": ["温柔", "执着", "寂寞", "善于倾听", "内心孤独"],
      "overt_motivation": "找到回到现实世界的方法",
      "covert_motivation": "陪伴沈念——即使以为她听不见也想说话给她听",
      "secret_fear": "被彻底忘记（他以为沈念早已忘记了他）",
      "misperception_of_other": "以为沈念听不见他说话，以为沈念早忘了他",
      "hidden_connection": "三年前就认识沈念，曾是她的邻桌"
    }
  ],
  "supporting_characters": [
    {
      "name": "林薇",
      "function": "阻碍",
      "identity": "霸凌者团体首领",
      "description": "带头霸凌沈念的女生，家庭优越，嫉妒沈念的才华"
    },
    {
      "name": "陈老师",
      "function": "助力",
      "identity": "高三班主任",
      "description": "注意到沈念的异常出勤，关心但不知真相"
    },
    {
      "name": "周晓",
      "function": "助力",
      "identity": "沈念的同学",
      "description": "沈念唯一的朋友，曾帮助她躲避霸凌"
    }
  ],
  "relationship_dynamics": "沈念和沈逸初期：沈念在透明状态下看见沈逸，以为出现幻觉。沈逸以为沈念听不见他说话，依然自顾自地说着三年来想说的话。中期：沈念发现沈逸是被困在透明层的人，开始试图交流。沈逸震惊地发现沈念能听见，但同时发现她会在24小时后忘记一切。后期：两人在24小时内建立了深刻的情感连接，但倒计时一直在走。最终：沈念在遗忘前最后一刻看清了沈逸的脸，记住了他的名字，然后一切归零——她忘了他，但她手腕上多了一道不知何时留下的红痕。"
