      "name": "林薇",
      "function": "阻碍",
      "identity": "霸凌者团体首领",
      "description": "带头霸凌沈念的女生，家庭优越，嫉妒沈念的才华"
    },
    {
      "name": "陈老师",
      "function": "助力",
      "identity": "高三班主任",
      "description": "注意到沈念的异常出勤，关心但不知真相"
    },
    {
