                "type": "string",
                "description": "本章故事梗概（自然语言叙述，200-400字）- 描述起始状态、主角核心行动、主要冲突展开、在整幕中的作用、结束状态",
                "minLength": 200,
                "maxLength": 400
              },
              "scene_sequence": {
                "type": "array",
                "description": "本章场景序列（按时间顺序排列，至少3个场景）",
                "minItems": 3,
                "items": {
                  "type": "object",
                  "required": [
                    "scene_number",
                    "scene_location",
                    "characters_present",
                    "scene_purpose",
                    "core_action",
                    "conflict_point",
                    "emotional_shift",
                    "scene_outcome"
